import{_ as e,o as a,c as n,a3 as r}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/latency-numbers.md","filePath":"appendix/latency-numbers.md"}'),l={name:"appendix/latency-numbers.md"};function p(t,s,i,o,c,d){return a(),n("div",null,[...s[0]||(s[0]=[r(`<h3 id="latency-numbers-every-programmer-should-know" tabindex="-1">Latency numbers every programmer should know <a class="header-anchor" href="#latency-numbers-every-programmer-should-know" aria-label="Permalink to &quot;Latency numbers every programmer should know&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Latency Comparison Numbers</span></span>
<span class="line"><span>--------------------------</span></span>
<span class="line"><span>L1 cache reference                           0.5 ns</span></span>
<span class="line"><span>Branch mispredict                            5   ns</span></span>
<span class="line"><span>L2 cache reference                           7   ns                      14x L1 cache</span></span>
<span class="line"><span>Mutex lock/unlock                           25   ns</span></span>
<span class="line"><span>Main memory reference                      100   ns                      20x L2 cache, 200x L1 cache</span></span>
<span class="line"><span>Compress 1K bytes with Zippy            10,000   ns       10 us</span></span>
<span class="line"><span>Send 1 KB bytes over 1 Gbps network     10,000   ns       10 us</span></span>
<span class="line"><span>Read 4 KB randomly from SSD*           150,000   ns      150 us          ~1GB/sec SSD</span></span>
<span class="line"><span>Read 1 MB sequentially from memory     250,000   ns      250 us</span></span>
<span class="line"><span>Round trip within same datacenter      500,000   ns      500 us</span></span>
<span class="line"><span>Read 1 MB sequentially from SSD*     1,000,000   ns    1,000 us    1 ms  ~1GB/sec SSD, 4X memory</span></span>
<span class="line"><span>HDD seek                            10,000,000   ns   10,000 us   10 ms  20x datacenter roundtrip</span></span>
<span class="line"><span>Read 1 MB sequentially from 1 Gbps  10,000,000   ns   10,000 us   10 ms  40x memory, 10X SSD</span></span>
<span class="line"><span>Read 1 MB sequentially from HDD     30,000,000   ns   30,000 us   30 ms 120x memory, 30X SSD</span></span>
<span class="line"><span>Send packet CA-&gt;Netherlands-&gt;CA    150,000,000   ns  150,000 us  150 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Notes</span></span>
<span class="line"><span>-----</span></span>
<span class="line"><span>1 ns = 10^-9 seconds</span></span>
<span class="line"><span>1 us = 10^-6 seconds = 1,000 ns</span></span>
<span class="line"><span>1 ms = 10^-3 seconds = 1,000 us = 1,000,000 ns</span></span></code></pre></div><p>Handy metrics based on numbers above:</p><ul><li>Read sequentially from HDD at 30 MB/s</li><li>Read sequentially from 1 Gbps Ethernet at 100 MB/s</li><li>Read sequentially from SSD at 1 GB/s</li><li>Read sequentially from main memory at 4 GB/s</li><li>6-7 world-wide round trips per second</li><li>2,000 round trips per second within a data center</li></ul><h4 id="latency-numbers-visualized" tabindex="-1">Latency numbers visualized <a class="header-anchor" href="#latency-numbers-visualized" aria-label="Permalink to &quot;Latency numbers visualized&quot;">​</a></h4><p><img src="https://camo.githubusercontent.com/77f72259e1eb58596b564d1ad823af1853bc60a3/687474703a2f2f692e696d6775722e636f6d2f6b307431652e706e67" alt=""></p><h4 id="source-s-and-further-reading" tabindex="-1">Source(s) and further reading <a class="header-anchor" href="#source-s-and-further-reading" aria-label="Permalink to &quot;Source(s) and further reading&quot;">​</a></h4><ul><li><a href="https://gist.github.com/jboner/2841832" target="_blank" rel="noreferrer">Latency numbers every programmer should know - 1</a></li><li><a href="https://gist.github.com/hellerbarde/2843375" target="_blank" rel="noreferrer">Latency numbers every programmer should know - 2</a></li><li><a href="http://www.cs.cornell.edu/projects/ladis2009/talks/dean-keynote-ladis2009.pdf" target="_blank" rel="noreferrer">Designs, lessons, and advice from building large distributed systems</a></li><li><a href="https://static.googleusercontent.com/media/research.google.com/en//people/jeff/stanford-295-talk.pdf" target="_blank" rel="noreferrer">Software Engineering Advice from Building Large-Scale Distributed Systems</a></li></ul>`,8)])])}const h=e(l,[["render",p]]);export{m as __pageData,h as default};
